  edit('onclick','stamp','Stamp on a click', [['dot(40, "gold")','color("teal")\n    stamp()']], 'The callback can leave a copy of the pointer before it moves away.', 'Each click leaves a stamp and moves the pointer right.', 'Set shape("turtle") before registering the callback.', ['stamp()'], {syntax:'stamp()',previewCall:'turtle_clicked(0, 0)',previewNote:'After a click'});
