  edit('screen-click','coordinates','Read a click', [['dot(20, "teal")','dot(20, "teal")\n    print(round(x), round(y))']], 'Print the coordinates supplied to the callback.', 'Each click leaves a dot and prints its x and y position.', 'Click to the left of the center and check the sign of x.', ['print(round(x), round(y))'], {syntax:'print(round(x), round(y))',previewCall:'mark(60, 40)',previewNote:'After a click'});
  first('errors-name','Fix the command name');
  add('errors-name','variable','Define the value first','distance = 80\nforward(distance)', 'A variable must have a value before a command can use it.', 'A line drawn using the defined distance.', 'Rename distance to length in both places.', ['distance = 80'], {syntax:'distance = 80\nforward(distance)',watchFor:'Use the same spelling and capitalization at the assignment and at the command.'});
  add('errors-name','color-quotes','Quote a color name','color("purple")\npensize(5)\ncircle(40)', 'Quotes make purple a string. Without them, Python would look for a variable named purple.', 'A purple circle.', 'Store "purple" in a variable called shade, then use color(shade).', ['"purple"'], {syntax:'color("purple")'});
  first('errors-syntax','Close the parentheses');
  add('errors-syntax','colon','Finish a block header','for side in range(3):\n    forward(80)\n    left(120)', 'A loop header ends with a colon before its indented body.', 'A complete triangle from a correctly written loop.', 'Change the shape while keeping the colon and indentation.', ['range(3):'], {syntax:'for side in range(3):'});
  add('errors-syntax','comma','Separate arguments','dot(60, "coral")\nhideturtle()', 'A comma separates the size from the color inside the same call.', 'A coral dot.', 'Use dot(80, "gold"). Keep the comma between the arguments.', ['60, "coral"'], {syntax:'dot(60, "coral")'});
  first('errors-indent','Both lines repeat');
  add('errors-indent','outside','A turn outside the loop','for side in range(4):\n    forward(40)\nleft(90)\nforward(30)', 'The unindented turn runs once after all four forward movements.', 'A 160-pixel horizontal line, then a short upward line.', 'Indent left(90) and predict the new shape.', ['left(90)'], {syntax:'for side in range(4):\n    forward(40)\nleft(90)'});
  add('errors-indent','function','Two levels of indentation','def square():\n    for side in range(4):\n        forward(60)\n        left(90)\n\nsquare()', 'The loop is inside the function. The movement and turn are inside the loop.', 'A square drawn when the function is called.', 'Add an unindented square() call after turning 45 degrees.', ['        forward(60)'], {syntax:'def square():\n    for side in range(4):\n        forward(60)'});
  first('drawing-help','Restore a visible line');
