  add('drawing-help','call','Call the drawing function','def mark():\n    dot(60, "coral")\n\nmark()\nhideturtle()', 'A drawing function needs a call to run its body.', 'A coral dot appears when mark() runs.', 'Change the dot inside the function, then run the call again.', ['mark()'], {syntax:'mark()'});
  first('desktop','Try the shared commands');
  add('desktop','loop','A portable loop','for side in range(4):\n    forward(80)\n    left(90)', 'This drawing body also works with desktop Turtle. Test it here first.', 'An 80-pixel square.', 'For a desktop file, put from turtle import * above it and done() below it.', ['range(4)'], {syntax:'from turtle import *\n# Drawing code\ndone()',watchFor:'The browser supplies Turtle commands. The desktop import and done() belong in the desktop file.'});
  add('desktop','filled','A portable filled shape','color("teal")\nbegin_fill()\ncircle(50)\nend_fill()', 'The fill commands can travel with your drawing to desktop Python too.', 'A filled teal circle.', 'Try another color here before transferring the drawing.', ['begin_fill()'], {syntax:'from turtle import *\n# Drawing code\ndone()'});

