  add('rectangle','named-sizes','Name the dimensions','width = 100\nheight = 50\ncolor("coral")\npensize(4)\nfor pair in range(2):\n    forward(width)\n    left(90)\n    forward(height)\n    left(90)', 'Give each dimension a name so the shape is easy to resize.', 'A rectangle twice as wide as it is tall.', 'Swap the values assigned to width and height.', ['width','height'], {syntax:'width = 100\nheight = 50'});
