  edit('star-shape','small','A smaller star', [['forward(140)','forward(80)']], 'Shorten the lines while keeping the star’s 144-degree turns.', 'A compact five-point star.', 'Try a thicker pen to make the small star easier to see.', ['80'], {syntax:'forward(80)'});
