  edit('house-outline','door','Add a doorway', [['hideturtle()','penup()\ngoto(-15, -70)\nsetheading(90)\npendown()\nforward(45)\nright(90)\nforward(30)\nright(90)\nforward(45)\nhideturtle()']], 'Add a three-sided doorway after the house outline works.', 'A small doorway rests on the house’s bottom edge.', 'Change its height from 45 to 60 in both vertical movements.', ['goto(-15, -70)'], {syntax:'forward(45)\nright(90)\nforward(30)'});
  first('heart','A filled heart');
