  edit('heart','outline','Keep just the outline', [['begin_fill()','pensize(4)'],['end_fill()\n','']], 'Keep every movement and remove the fill pair.', 'A crimson heart outline.', 'Use a different outline color and pen width.', ['pensize(4)'], {syntax:'pensize(4)'});
  first('dashed-line','Eight dashes');
