  edit('dashed-line','corner','Dashes around a corner', [['    forward(10)','    forward(10)\n    left(15)']], 'Turn a little after each dash and gap.', 'A curved chain made from straight dashes.', 'Try turning right instead.', ['left(15)'], {syntax:'left(15)'});
