  edit('circle-rosette','small','Smaller petals', [['circle(40)','circle(25)']], 'Change the petal radius while keeping the eight evenly spaced directions.', 'A compact flower around the same gold center.', 'Make the center smaller too.', ['25'], {syntax:'circle(25)'});
